    output reg [3:0] q;
    always @(posedge clk) begin
        if (rst) begin
            q <= 4'b0000;
        end else begin
            q[0] <= d_in;
            q[1] <= q[0];
            q[2] <= q[1];
            q[3] <= q[2];
        end
    end
endmodule

module piso (clk,rst,sh_ld,d,q,d_out);
    input clk,rst,sh_ld;
    input [3:0] d;
    output reg[3:0] q;
    output wire d_out;

    assign d_out = q[0];

    always @(posedge clk) begin
        if(rst) begin
            q <= 4'b0000;
        end else begin
            if (sh_ld == 0) begin
                q <= d;
            end else begin
                q[0] <= q[1];
                q[1] <= q[2];
                q[2] <= q[3];
                q[3] <= 0;
            end
        end
    end
endmodule

